/*
 * A247976  Triangle read by rows: T(n,k) generated by m-gon expansions in the
 *          case of odd m with "vertex to vertex" version or even m with
 *          "vertex to side" version. (See comment for details.)
 * https://oeis.org/A247976
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  tabl, nonn
 * Formula:   a(n) is obtained by enumerating a triangular array * T(r,c) row
 *            by row. The entry T(r,c) is defined by * * T(1,1) = 1, * T(r,1)
 *            = 1, * T(r,r) = ⌊(r+1)/2⌋, * for 1 < c < r * – if r is odd:
 *            T(r,c) = (c ≤ (r+1)/2) ? T(r‑1,c) : T(r‑1,c‑1) + T(r‑1,c), * –
 *            if r is even: T(r,c) = (c < (r+2)/2) ? T(r‑1,c...
 * Range:     u8 n <= 224, u16 n <= 692, u32 n <= 1275, u64 n <= 1275,
 *            u128 n <= 1275, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>

/* Assumes seq_t and idx_t are defined by the build environment */
static const size_t MAX_ROW = 2048;   /* safely larger than needed for n up to 10000 */

/* Sequence value for index n (1‑based) */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* out of bounds; harmless return */

    /* Working rows stored on the stack – safe for any seq_t type */
    seq_t prev[MAX_ROW];
    seq_t curr[MAX_ROW];
    size_t prev_len = 0;           /* last processed row length */

    idx_t cumulative = 0;          /* number of terms computed so far */
    idx_t row = 0;
    seq_t result = 0;

    while (cumulative < n) {
        ++row;
        size_t row_len = (size_t)row;   /* how many terms in this row */

        /* first entry of the new row */
        curr[1] = 1;

        /* compute inner entries (if any) */
        if (row >= 3) {
            if (row & 1) { /* odd row */
                for (size_t k = 2; k < row_len; ++k) {
                    if (k <= (row_len + 1) / 2)
                        curr[k] = prev[k];
                    else
                        curr[k] = prev[k - 1] + prev[k];
                }
            } else {       /* even row */
                for (size_t k = 2; k < row_len; ++k) {
                    if (k < (row_len + 2) / 2)
                        curr[k] = prev[k - 1] + prev[k];
                    else
                        curr[k] = curr[k - row_len / 2];
                }
            }
        }

        /* last entry of the row */
        curr[row_len] = (seq_t)(row_len + 1) / 2;

        cumulative += (idx_t)row_len;

        if (cumulative >= n) {
            /* position within the current row (1‑based) */
            idx_t pos = n - (cumulative - (idx_t)row_len);
            result = curr[pos];
            break;
        }

        /* prepare prev row for next iteration */
        for (size_t i = 1; i <= row_len; ++i)
            prev[i] = curr[i];
        prev_len = row_len;
    }

    return result;
}
